const listings=[{id:'696148729',city:'almaty',title:'2-комнатная квартира',address:'Аль-Фараби — Желтоксан · Бостандыкский р-н',details:'58 м² · 5/9 этаж · монолитный дом',price:'83 500 000 ₸',m2:'1 440 000 ₸/м²',event:'new',eventLabel:'Новая публикация',time:'10:24',thumb:'AR',tone:'',description:'Свежий ремонт, панорамные окна, тихий двор. До Esentai Mall — 7 минут.',matches:3,matchLabel:'3 заявки',agent:'',profile:'Покупатели до 90 млн'},{id:'696147301',city:'almaty',title:'1-комнатная квартира',address:'мкр. Дарабоз · Алатауский р-н',details:'41 м² · 7/12 этаж · 2025 г.п.',price:'27 900 000 ₸',m2:'680 488 ₸/м²',event:'match',eventLabel:'Совпадение с заявкой',time:'09:58',thumb:'DA',tone:'lime',description:'Новая квартира от собственника. Подходит под заявку «до 30 млн, новый дом».',matches:2,matchLabel:'2 заявки',agent:'НК',profile:'Новые ЖК · Алматы'},{id:'696145882',city:'astana',title:'3-комнатная квартира',address:'ул. Сыганак · Есильский р-н',details:'86 м² · 10/17 этаж · 2019 г.п.',price:'63 000 000 ₸',m2:'732 558 ₸/м²',event:'price',eventLabel:'Цена снижена на 4%',time:'09:32',thumb:'SK',tone:'violet',description:'Продавец снизил цену второй раз за месяц. История объекта — 21 день.',matches:1,matchLabel:'1 заявка',agent:'ДП',profile:'Семейные · Астана'},{id:'696143190',city:'almaty',title:'2-комнатная квартира',address:'ЖК Arena Park · Алатауский р-н',details:'50 м² · 9/12 этаж · 2024 г.п.',price:'46 500 000 ₸',m2:'930 000 ₸/м²',event:'new',eventLabel:'Новая публикация',time:'09:11',thumb:'AP',tone:'amber',description:'Полностью меблирована, окна во двор. Первое наблюдение — 14 минут назад.',matches:0,matchLabel:'Без заявки',agent:'',profile:'Инвестиции · Алматы'},{id:'696141728',city:'almaty',title:'3-комнатная квартира',address:'ул. Шашкина · Медеуский р-н',details:'74 м² · 3/5 этаж · 1987 г.п.',price:'57 000 000 ₸',m2:'770 270 ₸/м²',event:'match',eventLabel:'Совпадение с заявкой',time:'08:47',thumb:'MS',tone:'violet',description:'Кирпичный дом, закрытый двор, рядом школы. Совпадает с запросом семьи К.',matches:1,matchLabel:'1 заявка',agent:'АБ',profile:'Семьи · Медеуский'},{id:'696139442',city:'astana',title:'1-комнатная квартира',address:'ЖК Highvill · Алматы р-н',details:'38 м² · 6/10 этаж · 2022 г.п.',price:'31 800 000 ₸',m2:'836 842 ₸/м²',event:'new',eventLabel:'Новая публикация',time:'08:19',thumb:'HV',tone:'lime',description:'Новый ремонт, вид на набережную. Требует проверки статуса продавца.',matches:0,matchLabel:'Нужна проверка',agent:'',profile:'Новостройки · Астана'}];
const profiles=[{name:'Покупатели до 90 млн',meta:'Алматы · 2–3 комнаты',count:14,color:'cyan',telegram:true},{name:'Новые ЖК · Алматы',meta:'до 50 млн · от 2023 г.п.',count:9,color:'lime',telegram:true},{name:'Семейные · Астана',meta:'3 комнаты · от 70 м²',count:6,color:'violet',telegram:true},{name:'Инвестиции · Алматы',meta:'до 55 млн · цена/м²',count:4,color:'amber',telegram:false}];
let state={query:'',city:'all',event:'all',matchOnly:false,claimed:new Set(),shown:6};const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}function eventClass(t){return t==='price'?'price':t==='match'?'match':t==='existing'?'existing':'new'}
function renderProfiles(){$('#profileList').innerHTML=profiles.map(p=>`<button class="monitor-profile" type="button" data-profile="${esc(p.name)}"><span class="profile-color ${p.color==='cyan'?'':p.color}"></span><span><strong>${esc(p.name)}</strong><small>${esc(p.meta)}</small></span><b class="profile-count">${p.count}</b>${p.telegram?'<span class="profile-telegram">◉</span>':''}</button>`).join('')}
function filtered(){const q=state.query.toLowerCase();return listings.filter(l=>(state.city==='all'||l.city===state.city)&&(state.event==='all'||l.event===state.event)&&(!state.matchOnly||l.matches>0)&&(!q||`${l.title} ${l.address} ${l.details} ${l.description} ${l.profile}`.toLowerCase().includes(q))).slice(0,state.shown)}
function renderList(){const items=filtered();$('#resultCount').textContent=`${items.length} из ${listings.length} сигналов`;$('#loadMoreBtn').style.display=state.shown<listings.length?'inline-flex':'none';if(!items.length){$('#signalList').innerHTML='<div class="empty-state"><strong>Сигналы не найдены</strong><span>Измени фильтры или создай новый профиль мониторинга.</span></div>';return}$('#signalList').innerHTML=items.map(l=>{const claimed=state.claimed.has(l.id);return `<article class="signal-card" data-id="${l.id}"><div class="property-thumb ${l.tone?`thumb-${l.tone}`:''}"><span>${esc(l.thumb)}</span></div><div class="signal-main"><div class="signal-topline"><h3>${esc(l.title)}</h3><span class="event-badge ${eventClass(l.event)}">${l.event==='new'?'●':l.event==='price'?'↓':'◆'} ${esc(l.eventLabel)}</span></div><div class="signal-subline"><span>${esc(l.address)}</span><span class="dot-sep">·</span><span>${esc(l.time)}</span></div><p class="signal-description">${esc(l.description)}</p><div class="signal-meta"><span class="meta-chip">${esc(l.details)}</span><span class="meta-chip">${esc(l.profile)}</span>${l.matches?`<span class="match-chip">${esc(l.matchLabel)}</span>`:'<span class="meta-chip">Нужна проверка</span>'}</div></div><div class="signal-actions"><div><div class="signal-price">${esc(l.price)}</div><div class="price-m2">${esc(l.m2)}</div></div><div class="action-row"><button class="mini-action" type="button" data-open="${l.id}">Карточка</button><button class="mini-action ${claimed?'claimed':''}" type="button" data-claim="${l.id}">${claimed?`✓ ${esc(l.agent)}`:'Взять в работу'}</button></div></div></article>`}).join('')}
function toast(title,message){const item=document.createElement('div');item.className='toast';item.innerHTML=`<strong>${esc(title)}</strong><span>${esc(message)}</span>`;$('#toastStack').appendChild(item);setTimeout(()=>item.remove(),3600)}function openModal(){$('#modalBackdrop').classList.remove('hidden');setTimeout(()=>$('#profileForm input[name=name]').focus(),30)}function closeModal(){$('#modalBackdrop').classList.add('hidden')}
function updateView(view){const titles={feed:'Лента сигналов',profiles:'Профили мониторинга',buyers:'Заявки покупателей',team:'Команда',analytics:'Аналитика',integrations:'Интеграции',settings:'Настройки'};$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#viewTitle').textContent=titles[view]||titles.feed;if(view!=='feed')toast(titles[view],view==='profiles'?'Профили доступны в правой панели — выбери профиль или создай новый.':'Раздел готовится к подключению в следующем рабочем контуре.')}
function bind(){$('#searchInput').addEventListener('input',e=>{state.query=e.target.value;renderList()});$('#cityFilter').addEventListener('change',e=>{state.city=e.target.value;renderList()});$('#eventFilter').addEventListener('change',e=>{state.event=e.target.value;renderList()});$('#matchOnly').addEventListener('change',e=>{state.matchOnly=e.target.checked;renderList()});$('#resetFilters').addEventListener('click',()=>{state={...state,query:'',city:'all',event:'all',matchOnly:false,shown:6};$('#searchInput').value='';$('#cityFilter').value='all';$('#eventFilter').value='all';$('#matchOnly').checked=false;renderList();toast('Фильтры сброшены','Показываю все демо-сигналы.')});$('#loadMoreBtn').addEventListener('click',()=>{state.shown=listings.length;renderList()});$('#refreshBtn').addEventListener('click',()=>{const b=$('#refreshBtn');b.disabled=true;b.innerHTML='<span>↻</span> Проверяю…';$('#syncText').textContent='проверка';setTimeout(()=>{b.disabled=false;b.innerHTML='<span>↻</span> Обновить';$('#syncText').textContent='демо';$('#lastCheck').textContent='локальные данные';toast('Демо-поток обновлён','Показаны синтетические сигналы · реальный источник ожидает конфигурацию.')},850)});['#newProfileBtn','#addProfileMini'].forEach(s=>$(s).addEventListener('click',openModal));$('#modalClose').addEventListener('click',closeModal);$('#modalCancel').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});$('#profileForm').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);profiles.unshift({name:d.get('name'),meta:`${d.get('city')} · ${d.get('deal')}`,count:0,color:'cyan',telegram:d.get('channel')!=='Пока не подключать'});renderProfiles();closeModal();e.target.reset();toast('Профиль создан','Совпадения появятся после подключения разрешённого источника.')});$('#signalList').addEventListener('click',e=>{const open=e.target.closest('[data-open]');const claim=e.target.closest('[data-claim]');if(open){const l=listings.find(x=>x.id===open.dataset.open);toast('Карточка объекта',`${l.title} · ${l.address}`)}if(claim){const l=listings.find(x=>x.id===claim.dataset.claim);if(state.claimed.has(l.id)){state.claimed.delete(l.id);toast('Объект возвращён в очередь',l.title)}else{state.claimed.add(l.id);l.agent='АК';toast('Объект взят в работу',`${l.title} закреплён за Алексеем`)}$('#claimedMetric').textContent=state.claimed.size;renderList()}});$('#mainNav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)updateView(b.dataset.view)});$('#allProfilesBtn').addEventListener('click',()=>{updateView('profiles');toast('Профили мониторинга','Выбери профиль справа или добавь новый.')});$('#sourceDetailsBtn').addEventListener('click',()=>toast('Состояние адаптера','Демо-режим: укажи KRISHA_SOURCE_URL в секретах Site, чтобы включить авторизованный канал.'));$('#helpBtn').addEventListener('click',()=>toast('Центр помощи','Спроси команду поддержки или открой документацию проекта.'));$('#notificationsBtn').addEventListener('click',()=>toast('Уведомления','2 синтетических события требуют проверки'));$('#workspaceBtn').addEventListener('click',()=>toast('Рабочее пространство','Atlas Realty · Алматы'));$('#profileBtn').addEventListener('click',()=>toast('Профиль','Алексей Ким · руководитель'))}
async function hydrateSourceStatus(){try{const response=await fetch('/api/source-status');const data=await response.json();if(data.status==='healthy'||data.status==='partial'){$('#syncText').textContent='live';$('#sourceStatusLabel').textContent='BeautifulSoup активен';$('#sourceStatusHint').textContent=`Krisha.kz · ${data.count||0} объявлений`;$('[data-source-title]').textContent='Krisha.kz · BeautifulSoup';$('#sourceLiveBadge').textContent=data.status==='partial'?'частично':'live';$('#lastCheck').textContent=data.updated_at?new Date(data.updated_at).toLocaleString('ru-RU'):'—';$('#activeSegments').textContent=`${(data.checked_urls||[]).length} / ${(data.checked_urls||[]).length}`;$('#sourceCount').textContent=data.count||0;$('#sourceCoverageBar').style.width=data.status==='healthy'?'100%':'55%';$('#sourceCoverageBar').classList.toggle('source-partial',data.status==='partial');$('#coverageMetric').innerHTML=`${data.status==='healthy'?100:55}<span class="unit">%</span>`;}else{$('#syncText').textContent='ожидание';$('#sourceStatusLabel').textContent='Ожидает первого прохода';$('#sourceStatusHint').textContent='Krisha.kz · запуск через GitHub Actions';}}catch{}}
renderProfiles();renderList();bind();hydrateSourceStatus();

// Production bridge: the UI keeps a useful demo fallback, while this layer hydrates
// durable D1 data and turns the feed into a lightweight CRM workspace when available.
const api=async(path,options={})=>{const response=await fetch(path,{headers:{'content-type':'application/json',...(options.headers||{})},...options});if(!response.ok)throw new Error(`api_${response.status}`);return response.json()};
function crmCards(items){return items.slice(0,8).map(item=>`<article class="crm-card"><div class="crm-card-top"><span class="crm-avatar">${esc((item.title||'О').slice(0,2).toUpperCase())}</span><span class="event-badge ${eventClass(item.event_type||'new')}">${item.event_type==='price'?'Цена изменена':item.event_type==='existing'?'Объявление':'Новый объект'}</span></div><strong>${esc(item.title||'Объект')}</strong><small>${esc(item.address||'Адрес уточняется')}</small><div class="crm-card-foot"><b>${item.price_kzt?Number(item.price_kzt).toLocaleString('ru-RU')+' ₸':'цена н/д'}</b><button class="mini-action" data-crm-claim="${esc(item.source_id||'')}">В работу</button></div></article>`).join('')||'<div class="crm-empty">Пока нет карточек. Запусти синхронизацию источника.</div>'}
async function loadLiveData(sync=false){try{const payload=await api(`/api/events${sync?'?sync=1':''}`);if(Array.isArray(payload.items)&&payload.items.length){$('#newTodayMetric').textContent=payload.items.filter(item=>item.event_type==='new'&&item.observed_at&&Date.now()-new Date(item.observed_at).getTime()<86400000).length;listings.splice(0,listings.length,...payload.items.map(item=>({...item,id:item.source_id||item.id,city:String(item.city||'').toLowerCase().includes('аст')?'astana':'almaty',event:item.event_type||'new',eventLabel:item.event_type==='price'?'Цена изменена':item.event_type==='new'?'Новая публикация':item.event_type==='existing'?'В базе':'Совпадение с заявкой',price:item.price_kzt?Number(item.price_kzt).toLocaleString('ru-RU')+' ₸':'Цена по запросу',m2:item.area_m2&&item.price_kzt?Math.round(item.price_kzt/item.area_m2).toLocaleString('ru-RU')+' ₸/м²':'',details:[item.area_m2?`${item.area_m2} м²`:null,item.floor&&item.floors_total?`${item.floor}/${item.floors_total} этаж`:null].filter(Boolean).join(' · '),description:item.description||'',matches:0,matchLabel:'',thumb:'KR',tone:'',time:item.observed_at?new Date(item.observed_at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):''})));state.shown=Math.max(6,listings.length);renderList();$('#feedHeading').textContent='Новые сигналы · live';$('#lastCheck').textContent=payload.source?.updated_at?new Date(payload.source.updated_at).toLocaleString('ru-RU'):'ожидает первого прохода';$('#syncText').textContent='подключён'}const profilesPayload=await api('/api/profiles');if(Array.isArray(profilesPayload.items)&&profilesPayload.items.length){profiles.splice(0,profiles.length,...profilesPayload.items.map(p=>({...p,count:0,color:'cyan',telegram:Boolean(p.telegram_chat_id)})));renderProfiles()}}catch(error){console.debug('live data unavailable',error)}}
function renderCrm(view){const labels={profiles:['Профили мониторинга','Сегменты, которые сами находят нужные объекты'],buyers:['Заявки покупателей','Воронка клиентов и следующий шаг по каждой заявке'],team:['Команда','Распределение объектов и скорость реакции агентов'],analytics:['Аналитика','Срез рынка, конверсия сигналов и нагрузка команды'],integrations:['Интеграции','Krisha.kz, Telegram и CRM-связи'],settings:['Настройки','Правила уведомлений и доступы команды']};const [title,subtitle]=labels[view]||labels.buyers;const items=listings;const columns=view==='buyers'?[['Новые заявки','4'],['Подборка отправлена','3'],['Переговоры','2'],['Сделка','1']]:[['Новые сигналы',String(items.length)],['На проверке','3'],['В работе',String(state.claimed.size||2)],['Закрыто','8']];$('#crmView').innerHTML=`<section class="crm-head"><div><div class="eyebrow">CRM · ATLAS REALTY</div><h1>${esc(title)} <span class="title-mark">✦</span></h1><p>${esc(subtitle)}</p></div><div class="intro-actions"><button class="button secondary" id="crmRefresh" type="button">↻ Обновить</button><button class="button primary" id="crmPrimary" type="button">＋ Новая карточка</button></div></section><div class="crm-summary"><div><span>Активные карточки</span><strong>${items.length||16}</strong></div><div><span>Ответ за 15 минут</span><strong class="crm-positive">92%</strong></div><div><span>Команда онлайн</span><strong>3 / 5</strong></div><div><span>Конверсия в показ</span><strong>18.4%</strong></div></div><div class="crm-board">${columns.map((column,index)=>`<section class="crm-column"><div class="crm-column-head"><div><span class="crm-column-dot dot-${index}"></span><strong>${column[0]}</strong></div><b>${column[1]}</b></div>${crmCards(items.slice(index*2,index*2+2))}</section>`).join('')}</div>`;$('#crmRefresh').addEventListener('click',()=>loadLiveData(true).then(()=>{renderCrm(view);toast('CRM обновлена','Состояние синхронизировано с источником.')}));$('#crmPrimary').addEventListener('click',openModal);$('#crmView').addEventListener('click',e=>{const button=e.target.closest('[data-crm-claim]');if(button){api('/api/claims',{method:'POST',body:JSON.stringify({source_id:button.dataset.crmClaim,agent_name:'Алексей Ким'})}).then(()=>toast('Карточка закреплена','Объект добавлен в рабочую очередь.')).catch(()=>toast('CRM пока в демо-режиме','Подключи D1, чтобы сохранять изменения.'))}})}
document.querySelector('#mainNav').addEventListener('click',event=>{const button=event.target.closest('[data-view]');if(!button)return;const view=button.dataset.view;const feedSections=['#feedHeader','.stats-grid','.control-bar','.dashboard-grid'];const isFeed=view==='feed';feedSections.forEach(selector=>document.querySelector(selector)?.classList.toggle('hidden',!isFeed));$('#crmView').classList.toggle('hidden',isFeed);if(!isFeed)renderCrm(view)});
document.querySelector('#refreshBtn')?.addEventListener('click',()=>loadLiveData(true));
document.querySelector('#profileForm')?.addEventListener('submit',event=>{const data=new FormData(event.target);api('/api/profiles',{method:'POST',body:JSON.stringify({name:data.get('name'),city:data.get('city'),price_max_kzt:Number(String(data.get('max')||'').replace(/\D/g,''))||null})}).then(()=>loadLiveData()).catch(()=>{});});
loadLiveData(false);

